import { expect, test } from "bun:test";
import { endianness } from "node:os";
import { mkdirSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { confine, sandboxStatus } from "./sandbox.ts";
import { AUDIT_ARCH, DENIED, HOST_ABIS, X32_BIT, filterBytes, type Abi } from "./seccomp.ts";

// The generated bytes, read back as the kernel reads them: the cBPF interpreter of seccomp's subset (load of a field
// of seccomp_data, jumps on equal and on greater or equal, return).
const ALLOW = 0x7fff0000;
function verdict(bytes: Uint8Array, arch: number, nr: number): number {
  const v = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const le = endianness() === "LE";
  let a = 0, pc = 0;
  for (let steps = 0; steps < 1000; steps++) {
    const code = v.getUint16(pc * 8, le), jt = v.getUint8(pc * 8 + 2), jf = v.getUint8(pc * 8 + 3), k = v.getUint32(pc * 8 + 4, le);
    pc++;
    if (code === 0x20) a = k === 0 ? nr >>> 0 : k === 4 ? arch : NaN; // BPF_LD | BPF_W | BPF_ABS
    else if (code === 0x15) pc += a === k ? jt : jf; // BPF_JMP | BPF_JEQ | BPF_K
    else if (code === 0x35) pc += a >= k ? jt : jf; // BPF_JMP | BPF_JGE | BPF_K
    else if (code === 0x06) return k; // BPF_RET | BPF_K
    else throw new Error(`opcode ${code.toString(16)} is not one the program may hold`);
  }
  throw new Error("the program does not end");
}
const EPERM = 0x00050001;

// The denied list each architecture's program decodes to is the table's: every listed number, the x32 range of
// x86_64, an unknown architecture, and nothing else among the numbers a kernel has.
for (const [host, abis] of Object.entries(HOST_ABIS)) {
  test(`the filter for ${host} denies exactly the listed calls with EPERM`, () => {
    const bytes = filterBytes(abis);
    expect(bytes.length % 8).toBe(0);
    for (const abi of abis) {
      const denied: number[] = [];
      for (let nr = 0; nr < 1024; nr++) {
        const r = verdict(bytes, AUDIT_ARCH[abi], nr);
        if (r !== ALLOW) { expect(r).toBe(EPERM); denied.push(nr); }
      }
      expect([abi, denied]).toEqual([abi, DENIED.map((d) => d.nr[abi]).sort((x, y) => x - y)]);
      // The x32 bit is the x86_64 ABI's alone: its numbers all go, the others' ABIs have no such range.
      const x32 = [0, 1, 39, 231, 500].map((n) => verdict(bytes, AUDIT_ARCH[abi], X32_BIT + n));
      expect([abi, x32.every((r) => r === EPERM)]).toEqual([abi, abi === "x86_64"]);
    }
    // An architecture the program does not know is not run as one it does.
    expect(verdict(bytes, 0x12345678, 39)).toBe(EPERM);
  });
}
test("the denied table names each call once, with a reason, and the ABIs' numbers differ", () => {
  expect(DENIED.map((d) => d.name)).toEqual(["add_key", "request_key", "keyctl"]);
  for (const d of DENIED) {
    expect(d.why.length).toBeGreaterThan(20);
    expect(new Set(Object.values(d.nr)).size).toBe(Object.keys(AUDIT_ARCH).length);
  }
});

// In a sandbox, from a helper that makes the raw calls (python's ctypes: a build needs no compiler): keyctl and the
// x32 range get EPERM, and what a build, a test run and git do goes on working.
const python = Bun.which("python3");
const helper = `import ctypes, sys
libc = ctypes.CDLL(None, use_errno=True)
libc.syscall.restype = ctypes.c_long
def call(nr, *a):
    r = libc.syscall(ctypes.c_long(nr), *[ctypes.c_long(x) for x in a])
    return "ok" if r >= 0 else "errno-%d" % ctypes.get_errno()
mach = __import__("platform").machine()
keyctl = {"x86_64": 250, "aarch64": 219}[mach]
print("keyctl", call(keyctl, 0, -3, 0))  # KEYCTL_GET_KEYRING_ID of the session keyring, not created
if mach == "x86_64": print("x32", call(0x40000000 + 39))  # getpid by the x32 number
print("getpid", call(39 if mach == "x86_64" else 172))
`;
test.skipIf(!sandboxStatus().available || !sandboxStatus().seccomp || !python)("a sandboxed command gets EPERM from keyctl and x32 calls, and ordinary work still runs", () => {
  const root = realpathSync(mkdtempSync(join(tmpdir(), "keel-seccomp-")));
  try {
    const ws = join(root, "ws");
    mkdirSync(ws);
    writeFileSync(join(ws, "helper.py"), helper);
    writeFileSync(join(ws, "tiny.test.ts"), `import { expect, test } from "bun:test";\ntest("adds", () => { expect(1 + 1).toBe(2); });\n`);
    const run = (script: string) => {
      const r = Bun.spawnSync(confine(["bash", "-c", script], { sandbox: "workspace-write", network: false }, ws), { cwd: ws, stdout: "pipe", stderr: "pipe", env: { ...process.env, GIT_CONFIG_GLOBAL: "/dev/null", GIT_CONFIG_NOSYSTEM: "1" } });
      return { code: r.exitCode, out: r.stdout.toString() + r.stderr.toString() };
    };
    const calls = run("python3 helper.py");
    expect(calls.out).toContain("keyctl errno-1\n"); // EPERM
    if (process.arch === "x64") expect(calls.out).toContain("x32 errno-1\n");
    expect(calls.out).toContain("getpid ok\n");
    // The filter is on the command and its children, and no descriptor of it is left in them.
    const own = run(`grep -E '^Seccomp:' /proc/self/status; echo "fds: $(ls /proc/self/fd | tr '\\n' ' ')"; sh -c 'grep -E "^Seccomp:" /proc/self/status'`);
    expect(own.out.match(/Seccomp:\s+2/g)?.length).toBe(2);
    expect(own.out).toMatch(/fds: \d/);
    expect(own.out).not.toMatch(/fds:.*\b6\b/);
    // Work: git (init, add, commit, status) and a test run in the workspace.
    const git = run("git init -q . && git add tiny.test.ts && git -c user.name=k -c user.email=k@k commit -q -m first && git status --short && echo git-ok");
    expect(git.out).toContain("git-ok");
    const bun = run(`${JSON.stringify(process.execPath)} test ./tiny.test.ts 2>&1 | tail -n 5`);
    expect(bun.out).toMatch(/1 pass\b/);
    expect(bun.out).toMatch(/\b0 fail\b/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
